import { styled, css } from "next-yak";
import { useState } from "react";

const Button = styled.button<{ $on: boolean }>`
  display: flex;
  cursor: pointer;
  ${({ $on }) => $on && css`color: red;`}
`;

export default function Component() {
  const [on, setOn] = useState(false);
  return <Button $on={on} onClick={() => setOn(!on)}>hi</Button>;
}

import { styled, css } from "@yak/react";
import { useState } from "react";
import { Title } from "./title";
import { yakWidth } from "./sizes.yak";

export default function App() {
  const [small, setSmall] = useState(false);

  return (
    <Center>
      <Yak
        $small={small}
        onClick={() => setSmall(!small)}
        src="/img/yak-jumping.png"
        alt="The yak mascot. Click it!"
      />
      <Title>yak</Title>
    </Center>
  );
}

const Center = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 32px;
  min-height: 100%;
`;

const Yak = styled.img<{ $small?: boolean }>`
  width: ${yakWidth.big};
  cursor: pointer;
  transition: width 0.3s, transform 0.2s;

  &:hover {
    transform: translateY(-8px) rotate(-4deg);
  }

  ${({ $small }) =>
    $small &&
    css`
      width: ${yakWidth.small};
    `}
`;

